/** Actual Golisopod. Synthetic opposing cards isolate the real two attacks; no older card is enabled here. */
public final class GeneratedRuleBatch84Test {
    static final UUID A=new UUID(0,8411),B=new UUID(0,8412);
    static final String BASIC="me4_en_025",CARD="me4_en_026",SLASH="critical-slash",POWER="boundless-power";
    static final CardDatabase DB=BundledRules.loadCardDefinitions();static final CombatCatalog DATA=BundledCombatData.load();
    static void check(boolean b,String s){GeneratedRuleBatch8Test.check(b,s);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return GeneratedRuleBatch13Test.hand(m,p,id);}
    static CardInstance obtain(ServerMatch m,UUID p,String id){var h=m.privateView(p).hand().stream().filter(c->c.definitionId().equals(id)).findFirst();if(h.isPresent())return h.get();var c=m.privateView(p).deck().stream().filter(v->v.definitionId().equals(id)).findFirst().orElseThrow();m.searchOwnDeckToHandByEffect(p,List.of(c.instanceId()));return c;}
    static void atomic(ServerMatch m,Runnable action){var a=m.privateView(A);var b=m.privateView(B);var v=m.clientView(A);var r=m.randomTranscript();reject(action);check(a.equals(m.privateView(A))&&b.equals(m.privateView(B))&&v.equals(m.clientView(A))&&r.equals(m.randomTranscript()),"Rejected declaration changed zones, field or RNG");}
    static AttackDefinition combo(boolean pierce){return BundledCombatData.attack(JsonParser.parseString("""
        {"id":"combo","nameZh":"Synthetic damage and effects","energyCost":{},"baseDamage":20,
         "damageType":"COLORLESS","effectSupport":"SUPPORTED","ignoresActiveDefenderDamageEffects":%s,
         "triggers":[{"trigger":"AFTER_ATTACK","effects":[
          {"type":"damage_counter","target":"OPPONENT_ACTIVE","amount":2},
          {"type":"paralyze","target":"OPPONENT_ACTIVE"}]}]}
        """.formatted(pierce)).getAsJsonObject(),EffectRegistry.standard());}
    static ServerMatch game(){return game(false,false,0);}
    static ServerMatch game(boolean copied,boolean pierce,int seedStart){
        UUID owner=copied?B:A;var defs=new ArrayList<CardDefinition>();var profiles=new HashMap<String,PokemonProfile>();
        for(String id:List.of(BASIC,CARD)){defs.add(DB.find(id).orElseThrow());profiles.put(id,DATA.pokemon(id).orElseThrow());}
        for(String id:List.of("base","water","wrong","item","evolved")){boolean pokemon=Set.of("base","evolved").contains(id),energy=Set.of("water","wrong").contains(id);defs.add(new CardDefinition(id,id,pokemon?CardCategory.POKEMON:energy?CardCategory.ENERGY:CardCategory.TRAINER,id.equals("item")?TrainerCategory.ITEM:TrainerCategory.NONE,"J",Set.of("international"),id.equals("base"),energy,60,Map.of(),EffectSupport.SUPPORTED,null));}
        var ability=ResumableAbilityTest.ability("ping","{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}");
        profiles.put("base",new PokemonProfile(1000,1,null,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(10,false),combo(pierce),CopyAttackTest.copier()),List.of(ability),EnergyType.COLORLESS));
        // Synthetic Stage2 descendant tests ordinary evolution clearing. It is not an invented real Golisopod evolution.
        profiles.put("evolved",new PokemonProfile(200,2,CARD,null,0,null,0,1,DATA.pokemon(CARD).orElseThrow().attacks(),List.of(),EnergyType.WATER,"Synthetic descendant","Golisopod"));
        var item=ComposedTrainerIntegrationTest.item("{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}");
        var combat=new CombatCatalog(profiles,Map.of("water",EnergyType.WATER,"wrong",EnergyType.FIRE),Map.of("item",item));
        String[] pool={BASIC,BASIC,CARD,CARD,"base","base","base","water","water","wrong","wrong","item","evolved"};
        for(int seed=seedStart;seed<seedStart+2000;seed++){
            var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,pool[i%pool.length]));decks.add(cards);}
            var m=new ServerMatch(A,B,decks.getFirst(),decks.getLast(),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(m.privateView(owner).hand().stream().noneMatch(c->c.definitionId().equals(BASIC))||m.privateView(owner).hand().stream().noneMatch(c->c.definitionId().equals("base"))||m.privateView(copied?A:B).hand().stream().filter(c->c.definitionId().equals("base")).count()<2)continue;
            for(UUID p:List.of(A,B)){m.chooseOpeningActive(p,hand(m,p,p.equals(owner)?BASIC:"base").instanceId());m.placeOpeningBench(p,hand(m,p,"base").instanceId());m.startAfterOpening(p);}
            OpeningTestSupport.complete(m,A,B,0);m.drawCardsByEffect(A,A,24);m.drawCardsByEffect(A,B,24);m.endTurn(A);m.endTurn(B);
            if(m.privateView(owner).hand().stream().noneMatch(c->c.definitionId().equals(CARD))||m.privateView(A).hand().stream().filter(c->c.definitionId().equals("water")).count()<3||m.privateView(A).hand().stream().filter(c->c.definitionId().equals("wrong")).count()<3||m.privateView(A).hand().stream().noneMatch(c->c.definitionId().equals("evolved"))||m.privateView(B).hand().stream().noneMatch(c->c.definitionId().equals("item")))continue;
            if(copied)m.endTurn(A);m.evolve(owner,active(m,owner),hand(m,owner,CARD).instanceId());if(copied)m.endTurn(B);return m;
        }throw new AssertionError("No actual Golisopod fixture "+copied+"/"+pierce+"/"+seedStart);
    }
    static void attach(ServerMatch m,String id){var c=obtain(m,A,id);m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,c.instanceId(),A,active(m,A));}
    static void settle(ServerMatch m){for(int i=0;i<16;i++){if(m.phase()==MatchPhase.PRIZE_SELECTION)m.takePrizeAt(m.pendingChoicePlayer(),0);else if(m.phase()==MatchPhase.CHOOSE_REPLACEMENT){UUID p=m.pendingChoicePlayer();m.chooseReplacement(p,m.benchPokemonView(p).getFirst().pokemonId());}else return;}throw new AssertionError("Unfinished KO continuation");}
    static void prepareLethal(ServerMatch m,boolean copied){if(copied)m.placeDamageCountersByEffect(A,B,active(m,B),11);else{m.placeDamageCountersByEffect(A,B,active(m,B),60);m.placeDamageCountersByEffect(A,B,active(m,B),37);}}
    static void copy(ServerMatch m,String id){var c=m.copyAttackOptions(A,"copy").stream().filter(o->o.attackId().equals(id)).findFirst().orElseThrow();m.copyAttackWithEnergyDiscards(A,"copy",c.pokemonId(),c.entrySequence(),c.attackId(),List.of(),List.of());}
    static void slashKo(ServerMatch m){attach(m,"water");prepareLethal(m,false);m.attack(A,SLASH);check(m.lastAttack().finalDamage()==30&&m.phase()==MatchPhase.PRIZE_SELECTION,"Actual W30 did not create damage KO/prize continuation");settle(m);check(m.currentPlayer().equals(B)&&m.phase()==MatchPhase.TURN&&m.privateView(A).prizes().size()==5,"Guard KO did not reach actual next opposing turn");}
    static void switchOutAndBack(ServerMatch m,UUID actor,UUID owner){UUID before=active(m,owner);m.switchActiveByEffect(actor,owner,m.benchPokemonView(owner).getFirst().pokemonId());m.switchActiveByEffect(actor,owner,before);}
    static void rule(ServerMatch m,UUID actor,String text){var effect=EffectRegistry.standard().parse(JsonParser.parseString(text).getAsJsonObject());m.executeEffectProgramByRule(actor,active(m,actor),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(effect)))),EffectTrigger.ON_CARD_PLAYED);}
    public static void main(String[]args){printed();costAndNonlethal();guardSourcesAndExpiry();guardPiercing();guardClearing();copiedSlash();powerCostsAndExpiry();powerClearing();copiedPower();System.out.println("GeneratedRuleBatch84Test passed: actual Wimpod evolution/140HP/Water/Lightning weakness/retreat2, W30 confirmed damage KO next-opponent-turn protection, attack damage/counters/status versus Ability/Trainer, expiry/Bench/devolution/leave/copy source, retained CCC150 and next-own-turn all-attack lock with expiry/Bench/evolution/copy clearing");}
    static void printed(){var c=DB.find(CARD).orElseThrow();var p=DATA.pokemon(CARD).orElseThrow();check(c.effectSupport()==EffectSupport.SUPPORTED&&!c.basicPokemon()&&p.hitPoints()==140&&p.pokemonType()==EnergyType.WATER&&p.weaknessType()==EnergyType.LIGHTNING&&p.weaknessMultiplier()==2&&p.resistanceType()==null&&p.retreatCost()==2&&p.prizeCards()==1&&p.evolvesFromDefinitionId().equals(BASIC)&&p.evolvesFromName().equals("Wimpod")&&p.abilities().isEmpty(),"Printed Golisopod metadata");
        check(p.attacks().size()==2&&p.attacks().getFirst().id().equals(SLASH)&&p.attacks().getFirst().baseDamage()==30&&p.attacks().getFirst().energyCost().equals(Map.of(EnergyType.WATER,1))&&p.attacks().getLast().id().equals(POWER)&&p.attacks().getLast().baseDamage()==150&&p.attacks().getLast().energyCost().equals(Map.of(EnergyType.COLORLESS,3)),"Printed attacks/costs");p.attacks().forEach(AttackProgramRules::validate);check(game().activePokemonView(A).evolutionCardIds().equals(List.of(BASIC,CARD)),"Actual normal Wimpod evolution");}
    static void costAndNonlethal(){var m=game();atomic(m,()->m.attack(A,SLASH));attach(m,"wrong");atomic(m,()->m.attack(A,SLASH));attach(m,"water");atomic(m,()->m.attack(B,SLASH));atomic(m,()->m.attack(A,"not-an-attack"));m.attack(A,SLASH);check(m.lastAttack().finalDamage()==30&&m.activePokemonView(B).damage()==30&&m.currentPlayer().equals(B),"Critical Slash normal damage");m.attack(B,"combo");check(m.lastAttack().finalDamage()==20&&m.activePokemonView(A).damage()==40&&m.activePokemonView(A).conditions().contains(SpecialCondition.PARALYZED),"Nonlethal Critical Slash wrongly granted protection");}
    static void guardSourcesAndExpiry(){var m=game();UUID source=active(m,A);slashKo(m);m.useAbility(B,active(m,B),"ping");check(m.activePokemonView(A).damage()==20,"Attack guard blocked actual Ability source");m.playTrainer(B,obtain(m,B,"item").instanceId(),null);check(m.activePokemonView(A).damage()==40,"Attack guard blocked actual Trainer source");m.attack(B,"combo");check(active(m,A).equals(source)&&m.lastAttack().finalDamage()==0&&m.activePokemonView(A).damage()==40&&m.activePokemonView(A).conditions().isEmpty()&&m.currentPlayer().equals(A),"Guard failed attack damage/counters/status or lost source");
        m.attack(A,SLASH);check(m.lastAttack().finalDamage()==30&&m.phase()==MatchPhase.TURN,"Nonlethal later slash changed behavior");m.attack(B,"combo");check(m.lastAttack().finalDamage()==20&&m.activePokemonView(A).damage()==80&&m.activePokemonView(A).conditions().contains(SpecialCondition.PARALYZED),"Expired KO guard leaked into a later opposing turn");}
    static void guardPiercing(){var m=game(false,true,0);slashKo(m);m.attack(B,"combo");check(m.lastAttack().finalDamage()==20&&m.activePokemonView(A).damage()==20&&m.activePokemonView(A).conditions().isEmpty(),"Ignore defender damage effects should bypass guard's damage only, not counters/status protection");}
    static void guardClearing(){
        var switched=game();slashKo(switched);switchOutAndBack(switched,B,A);switched.attack(B,"hit");check(switched.activePokemonView(A).damage()==10,"Bench round trip retained KO guard");
        var devolved=game();slashKo(devolved);devolved.devolvePokemonToHandByEffect(B,A,active(devolved,A));check(devolved.activePokemonView(A).evolutionCardIds().equals(List.of(BASIC)),"Synthetic rule devolution failed");devolved.attack(B,"hit");check(devolved.activePokemonView(A).damage()==10,"Devolution retained KO guard");
        var left=game();UUID departed=active(left,A);slashKo(left);rule(left,B,"{\"type\":\"return_to_hand\",\"target\":\"OPPONENT_ACTIVE\"}");settle(left);check(!active(left,A).equals(departed)&&left.privateView(A).hand().stream().anyMatch(c->c.definitionId().equals(CARD)),"Rule-origin leave did not return actual evolution stack");left.attack(B,"hit");check(left.activePokemonView(A).damage()==10,"Leaving protected source transferred guard to replacement");
    }
    static void copiedSlash(){var m=game(true,false,0);UUID source=active(m,A),donor=active(m,B);attach(m,"wrong");prepareLethal(m,true);copy(m,SLASH);check(m.lastAttack().finalDamage()==30&&m.phase()==MatchPhase.PRIZE_SELECTION,"Copied actual Critical Slash did not KO donor");settle(m);check(!active(m,B).equals(donor)&&m.privateView(B).discard().stream().anyMatch(c->c.definitionId().equals(CARD)),"Copied donor KO did not settle");m.attack(B,"combo");check(active(m,A).equals(source)&&m.activePokemonView(A).damage()==0&&m.activePokemonView(A).conditions().isEmpty()&&m.lastAttack().finalDamage()==0,"Copied guard attached to donor/replacement instead of actual copying source");m.endTurn(A);m.attack(B,"hit");check(m.activePokemonView(A).damage()==10,"Copied source guard did not expire");}
    static void paidPower(ServerMatch m){attach(m,"water");attach(m,"wrong");attach(m,"wrong");m.attack(A,POWER);check(m.lastAttack().finalDamage()==150&&m.activePokemonView(B).damage()==150&&m.currentPlayer().equals(B),"Boundless Power lost CCC150");}
    static void bothBlocked(ServerMatch m){check(!m.mayAttack(A),"Next-own-turn all-attack lock not shown to action surface");atomic(m,()->m.attack(A,SLASH));atomic(m,()->m.attack(A,POWER));}
    static void powerCostsAndExpiry(){var m=game();attach(m,"wrong");attach(m,"wrong");atomic(m,()->m.attack(A,POWER));attach(m,"water");m.attack(A,POWER);check(m.lastAttack().finalDamage()==150&&m.activePokemonView(B).damage()==150,"CCC accepts mixed colored Energy");m.attack(B,"hit");check(m.activePokemonView(A).damage()==10,"Boundless Power wrongly granted Critical Slash KO guard");bothBlocked(m);m.endTurn(A);m.endTurn(B);m.attack(A,SLASH);check(m.lastAttack().finalDamage()==30&&m.activePokemonView(B).damage()==180,"All-attack lock did not expire after next own turn");}
    static void powerClearing(){var switched=game();paidPower(switched);switched.endTurn(B);bothBlocked(switched);switchOutAndBack(switched,A,A);switched.attack(A,SLASH);check(switched.activePokemonView(B).damage()==180,"Bench round trip retained Boundless Power prohibition");
        var evolved=game();paidPower(evolved);evolved.endTurn(B);bothBlocked(evolved);evolved.evolve(A,active(evolved,A),obtain(evolved,A,"evolved").instanceId());check(evolved.activePokemonView(A).evolutionCardIds().equals(List.of(BASIC,CARD,"evolved")),"Synthetic Stage2 descendant did not evolve normally");evolved.attack(A,SLASH);check(evolved.activePokemonView(B).damage()==180,"Evolution retained all-attack prohibition");}
    static void copiedPower(){var m=game(true,false,0);attach(m,"wrong");UUID source=active(m,A);copy(m,POWER);check(m.lastAttack().finalDamage()==150&&m.phase()==MatchPhase.PRIZE_SELECTION,"Copied Boundless Power failed actual 150 damage");settle(m);m.attack(B,"hit");check(active(m,A).equals(source)&&m.activePokemonView(A).damage()==10,"Copied Boundless Power incorrectly created KO guard");check(!m.mayAttack(A),"Copied all-attack prohibition applied to donor instead of actual source");atomic(m,()->m.attack(A,"hit"));atomic(m,()->m.attack(A,"combo"));m.endTurn(A);m.endTurn(B);m.attack(A,"hit");check(m.lastAttack().finalDamage()==10,"Copied all-attack prohibition failed expiration");}
}
